mapper.select:
SELECT FROM ops_incidents
AND status <> 'RESOLVED' AND status = #{status}
ORDER BY CASE severity WHEN 'P0' THEN 0 WHEN 'P1' THEN 1 WHEN 'P2' THEN 2 ELSE 3 END, last_seen_at DESC, id DESC LIMIT #{limit}

mapper.update:
UPDATE ops_incidents
SET status = #{status},
    resolved_at = CASE WHEN #{status} = 'RESOLVED' THEN now() ELSE resolved_at END,
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE ops_incidents
SET status = 'RESOLVED',
    resolved_at = #{resolvedAt},
    updated_at = #{updatedAt}
WHERE status <> 'RESOLVED'
  AND last_seen_at < #{before}
